            if cut >= start:
                result.append((start, cut))
                start = cut + 1
        if start < size:
            result.append((start, size))
        return result

    row_spans, col_spans = spans(h, row_cuts), spans(w, col_cuts)
    # Each occupied pair of neighboring cells forms a horizontally mirrored
    # figure. Complete a missing half only when exactly one half is occupied.
    for r0, r1 in row_spans:
        for j in range(len(col_spans) - 1):
            a0, a1 = col_spans[j]
