 "content": "def transform(grid):
    """Copy a colored figure into the empty neighboring panel by reflection."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    row_cuts = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    col_cuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(size, cuts):
        res, start = [], 0
        for cut in cuts:
            res.append((start, cut))
            start = cut + 1
        res.append((start, size))
        return res

    rows, cols = spans(h, row_cuts), spans(w, col_cuts)
    # Compare each adjacent equal-width cell pair within a row band.
    for r0, r1 in rows:
        for i in range(len(cols) - 1):
            a0, a1 = cols[i]
            b0, b1 = cols[i + 1]
            if a1 - a0 != b1 - b0:
                continue
            a_has = any(grid[r][c] != 0 for r in range(r0, r1) for c in range(a0, a1))
            b_has = any(grid[r][c] != 0 for r in range(r0, r1) for c in range(b0, b1))
            if a_has == b_has:
                continue
            if a_has:
                src0, src1, dst1 = a0, a1, b1
            else:
                src0, src1, dst1 = b0, b1, a1
            for r in range(r0, r1):
                for c in range(src0, src1):
                    if grid[r][c] != 0:
                        out[r][dst1 - 1 - (c - src0)] = grid[r][c]
    return out
