 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Locate full horizontal and vertical separators.
    rcuts = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    ccuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    def spans(n, cuts):
        ans, start = [], 0
        for cut in cuts:
            ans.append((start, cut)); start = cut + 1
        ans.append((start, n))
        return ans
    rows, cols = spans(h, rcuts), spans(w, ccuts)
    # In each row band, the two rightmost panels contain corresponding
    # figures. Complete the rightmost figure as the horizontal reflection of
    # the neighboring panel; do not alter the original panel.
    if len(cols) >= 3:
        src0, src1 = cols[-2]
        dst0, dst1 = cols[-1]
        if src1-src0 == dst1-dst0:
            width = src1-src0
            for r0,r1 in rows:
                for r in range(r0,r1):
                    for k in range(width):
                        val = grid[r][src0+k]
                        if val != 0:
                            out[r][dst1-1-k] = val
    return out
