 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    row_cuts = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    col_cuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(size, cuts):
        result, start = [], 0
        for cut in cuts:
            result.append((start, cut))
            start = cut + 1
        result.append((start, size))
        return result

    row_spans = spans(h, row_cuts)
    col_spans = spans(w, col_cuts)

    def occupied(r0, r1, c0, c1):
        return any(grid[r][c] != 0 for r in range(r0, r1) for c in range(c0, c1))

    for r0, r1 in row_spans:
        pairs = []
        if len(col_spans) == 4 and all(col_spans[i+1][1] - col_spans[i+1][0] == col_spans[i][1] - col_spans[i][0] for i in (0, 2)):
            # In a four-cell-wide array, the cells form two independent pairs.
            pairs = [(0, 1), (2, 3)]
        else:
            # In the three complete-cell demonstrations, the active pair is
            # identified by a matching occupied pair; otherwise a lone object
            # in an outer cell pairs with its sole inner neighbor.
            adjacent = []
            for i in range(len(col_spans) - 1):
                a0, a1 = col_spans[i]
                b0, b1 = col_spans[i + 1]
                if a1 - a0 == b1 - b0:
                    ah, bh = occupied(r0, r1, a0, a1), occupied(r0, r1, b0, b1)
                    adjacent.append((i, i + 1, ah, bh))
            matched = [(i, j) for i, j, ah, bh in adjacent if ah and bh]
            if matched:
                pairs = matched
            else:
                candidates = [(i, j) for i, j, ah, bh in adjacent if ah != bh]
                # An outer singleton pairs inward; an interior singleton
                # pairs with the neighbor toward the center of the panel array.
                for i, j in candidates:
                    if i == 0 or j == len(col_spans) - 1:
                        pairs.append((i, j))
                    elif i == 1:
                        pairs.append((i, j))

        for i, j in pairs:
            a0, a1 = col_spans[i]
            b0, b1 = col_spans[j]
            if a1 - a0 != b1 - b0:
                continue
            width = a1 - a0
            for r in range(r0, r1):
                for k in range(width):
                    left = grid[r][a0 + k]
                    right = grid[r][b1 - 1 - k]
                    if left != 0:
                        out[r][b1 - 1 - k] = left
                    if right != 0:
                        out[r][a0 + k] = right
    return out

