 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Full-width and full-height colored lines divide the grid into panels.
    row_cuts = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    col_cuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(size, cuts):
        result, start = [], 0
        for cut in cuts:
            result.append((start, cut))
            start = cut + 1
        result.append((start, size))
        return result

    row_spans = spans(h, row_cuts)
    col_spans = spans(w, col_cuts)

    # The panels are arranged as mirrored pairs. In the regular layout the
    # two left cells and two right cells pair independently. If the final
    # cell is narrower than the others, the center two cells are the matching
    # pair instead (the narrow terminal cell is a margin).
    pairs = []
    if len(col_spans) == 4:
        widths = [b - a for a, b in col_spans]
        if widths[3] != widths[2]:
            pairs = [(0, 1), (1, 2)]
        else:
            pairs = [(0, 1), (2, 3)]
    else:
        pairs = [(i, i + 1) for i in range(0, len(col_spans) - 1, 2)]

    for r0, r1 in row_spans:
        for i, j in pairs:
            a0, a1 = col_spans[i]
            b0, b1 = col_spans[j]
            if a1 - a0 != b1 - b0:
                continue
            width = a1 - a0
            # Mirror corresponding pixels across the divider, in both
            # directions, while preserving any cells already present.
            for r in range(r0, r1):
                for k in range(width):
                    left = grid[r][a0 + k]
                    right = grid[r][b1 - 1 - k]
                    if left != 0:
                        out[r][b1 - 1 - k] = left
                    if right != 0:
                        out[r][a0 + k] = right
    return out

