        for cut in cuts:
            result.append((start, cut))
            start = cut + 1
        result.append((start, n))
        return result

    rows, cols = spans(h, row_cuts), spans(w, col_cuts)

    def has(r0, r1, c0, c1):
        return any(grid[r][c] != 0 for r in range(r0, r1) for c in range(c0, c1))

    # In each horizontal band, an object on one side of a cell divider is
    # reflected into the blank cell on its other side. Existing objects are
    # not modified; only missing mirrored pixels are added.
    for r0, r1 in rows:
