                src0, src1, dst1 = a0, a1, b1
            else:
                src0, src1, dst1 = b0, b1, a1
            for r in range(r0, r1):
                for k in range(src1 - src0):
                    value = grid[r][src0 + k]
                    if value:
                        out[r][dst1 - 1 - k] = value
