        # band is complete. Otherwise mirror isolated figures into an empty
        # equal-sized adjacent cell.
        already_paired = False
        for i in range(len(col_spans) - 1):
            a0, a1 = col_spans[i]
            b0, b1 = col_spans[i + 1]
