    """Mirror each cell across the divider within its adjacent panel pair."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Full-width / full-height colored lines delimit independent bands/cells.
    row_cuts = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    col_cuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(size, cuts):
        result, start = [], 0
        for cut in cuts:
            result.append((start, cut))
            start = cut + 1
        result.append((start, size))
        return result

    row_spans = spans(h, row_cuts)
    col_spans = spans(w, col_cuts)

    # Paired panels reflect horizontally across their shared separator.
    # Apply the reflection both ways, retaining all original non-background cells.
    for r0, r1 in row_spans:
        for i in range(0, len(col_spans) - 1, 2):
            a0, a1 = col_spans[i]
            b0, b1 = col_spans[i + 1]
            if a1 - a0 != b1 - b0:
                continue
            for r in range(r0, r1):
                for k in range(a1 - a0):
                    a = grid[r][a0 + k]
                    b = grid[r][b1 - 1 - k]
                    if a != 0:
                        out[r][b1 - 1 - k] = a
                    if b != 0:
                        out[r][a0 + k] = b
    return out

