 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    row_cuts = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    col_cuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(size, cuts):
        result, start = [], 0
        for cut in cuts:
            result.append((start, cut))
            start = cut + 1
        result.append((start, size))
        return result

    row_spans = spans(h, row_cuts)
    col_spans = spans(w, col_cuts)

    for r0, r1 in row_spans:
        # Identify already-complete neighboring mirror pairs.
        complete = set()
        for i in range(len(col_spans) - 1):
            a0, a1 = col_spans[i]
            b0, b1 = col_spans[i + 1]
            if a1 - a0 != b1 - b0:
                continue
            occupied = False
            equal = True
            for r in range(r0, r1):
                for k in range(a1 - a0):
                    a, b = grid[r][a0 + k], grid[r][b1 - 1 - k]
                    occupied |= (a != 0 or b != 0)
                    if a != b:
                        equal = False
            if occupied and equal:
                complete.add(i)

        # Each unmatched object is mirrored inward, toward the grid's center.
        # The two innermost cells therefore copy toward one another; outer
        # cells copy toward their only inner neighbor.
        for i, (c0, c1) in enumerate(col_spans):
            if not any(grid[r][c] != 0 for r in range(r0, r1) for c in range(c0, c1)):
                continue
            if i > 0 and (i - 1) in complete:
                continue
            if i < len(col_spans) - 1 and i in complete:
                continue
            if i < len(col_spans) // 2:
                j = i + 1
            else:
                j = i - 1
            if not (0 <= j < len(col_spans)):
                continue
            d0, d1 = col_spans[j]
            if c1 - c0 != d1 - d0:
                continue
            for r in range(r0, r1):
                for k in range(c1 - c0):
                    value = grid[r][c0 + k]
                    if value != 0 and out[r][d1 - 1 - k] == 0:
                        out[r][d1 - 1 - k] = value
    return out

