 "content": "def transform(grid):
    """Fill missing horizontal mirror copies within each separator band."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rowcuts = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    colcuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(size, cuts):
        result, start = [], 0
        for cut in cuts:
            result.append((start, cut))
            start = cut + 1
        result.append((start, size))
        return result

    row_spans = spans(h, rowcuts)
    col_spans = spans(w, colcuts)

    for r0, r1 in row_spans:
        for i in range(len(col_spans) - 1):
            a0, a1 = col_spans[i]
            b0, b1 = col_spans[i + 1]
            if a1 - a0 != b1 - b0:
                continue
            # Match overlay shapes, allowing the individual cells at mirrored
            # positions to differ where one side is a blank counterpart.
            left_cells = [grid[r][a0+k] for r in range(r0,r1) for k in range(a1-a0)]
            right_cells = [grid[r][b1-1-k] for r in range(r0,r1) for k in range(a1-a0)]
            left_obj = any(v != 0 for v in left_cells)
            right_obj = any(v != 0 for v in right_cells)
            if left_obj and not right_obj:
                for r in range(r0,r1):
                    for k in range(a1-a0):
                        v = grid[r][a0+k]
                        if v: out[r][b1-1-k] = v
            elif right_obj and not left_obj:
                for r in range(r0,r1):
                    for k in range(a1-a0):
                        v = grid[r][b1-1-k]
                        if v: out[r][a0+k] = v
            else:
                # The underlying design places an incomplete copy in some
                # panels even if both are occupied: reflect both sides to make
                # their shared pattern complete.
                for r in range(r0,r1):
                    for k in range(a1-a0):
                        left = grid[r][a0+k]
                        right = grid[r][b1-1-k]
                        if left and not right: out[r][b1-1-k] = left
                        if right and not left: out[r][a0+k] = right
    return out

