 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The separators define rectangular panels. Some panels contain a figure
    # and an adjacent panel contains its horizontal mirror; complete the pair.
    row_cuts = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    col_cuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    def spans(size, cuts):
        ans, start = [], 0
        for cut in cuts:
            ans.append((start, cut))
            start = cut + 1
        ans.append((start, size))
        return ans
    row_spans, col_spans = spans(h, row_cuts), spans(w, col_cuts)

    for r0, r1 in row_spans:
        for i in range(len(col_spans) - 1):
            a0, a1 = col_spans[i]
            b0, b1 = col_spans[i + 1]
            if a1 - a0 != b1 - b0:
                continue
            # Reflect when one panel has the motif and the other does not.
            a_has = any(grid[r][c] != 0 for r in range(r0, r1) for c in range(a0, a1))
            b_has = any(grid[r][c] != 0 for r in range(r0, r1) for c in range(b0, b1))
            if a_has == b_has:
                continue
            src0, src1, dst1 = (a0, a1, b1) if a_has else (b0, b1, a1)
            for r in range(r0, r1):
                for k in range(src1 - src0):
                    value = grid[r][src0 + k]
                    if value:
                        out[r][dst1 - 1 - k] = value
    return out

