 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Full-length colored lines divide the canvas into panels and bands.
    row_cuts = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    col_cuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(size, cuts):
        result, start = [], 0
        for cut in cuts:
            result.append((start, cut))
            start = cut + 1
        result.append((start, size))
        return result

    bands = spans(h, row_cuts)
    panels = spans(w, col_cuts)

    for r0, r1 in bands:
        # Identify adjacent panel pairs that already contain exact reflected
        # copies. A completed pair is not extended into further empty panels.
        completed = set()
        for i in range(len(panels) - 1):
            a0, a1 = panels[i]
            b0, b1 = panels[i + 1]
            if a1 - a0 != b1 - b0:
                continue
            has_marks = False
            same_reflection = True
            for r in range(r0, r1):
                for k in range(a1 - a0):
                    left = grid[r][a0 + k]
                    right = grid[r][b1 - 1 - k]
                    has_marks |= left != 0 or right != 0
                    if left != right:
                        same_reflection = False
            if has_marks and same_reflection:
                completed.update((i, i + 1))

        # A lone/incomplete figure is copied into each adjacent blank cell by
        # horizontal reflection. All decisions use the original input grid.
        for i, (c0, c1) in enumerate(panels):
            if i in completed:
                continue
            if not any(grid[r][c] != 0 for r in range(r0, r1) for c in range(c0, c1)):
                continue
            for j in (i - 1, i + 1):
                if j < 0 or j >= len(panels):
                    continue
                d0, d1 = panels[j]
                if d1 - d0 != c1 - c0:
                    continue
                if any(grid[r][c] != 0 for r in range(r0, r1) for c in range(d0, d1)):
                    continue
                for r in range(r0, r1):
                    for k in range(c1 - c0):
                        value = grid[r][c0 + k]
                        if value != 0:
                            out[r][d1 - 1 - k] = value
    return out

