    col_cuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    # Use only input marks as sources (no cascading) and keep divider colors intact.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or r in row_cuts or c in col_cuts:
                continue
            for cut in row_cuts:
                rr = 2 * cut - r
                if 0 <= rr < h and rr not in row_cuts:
                    out[rr][c] = color
            for cut in col_cuts:
                cc = 2 * cut - c
                if 0 <= cc < w and cc not in col_cuts:
                    out[r][cc] = color
    return out

