    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The grid has a regular separator lattice. Reflect each visible shape
    # from the left half of the cell array into its paired cell to the right.
    col_cuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
