        spans, start = [], 0
        for cut in cuts:
            spans.append((start, cut))
            start = cut + 1
        spans.append((start, n))
        return spans

    panels = spans(w, col_cuts)
    bands = spans(h, row_cuts)

    # For 4 panels, pair the outer cells with their inward neighbors. In the
    # 3-panel demo layout, the two left panels are a pair; the far-right narrow
    # margin is excluded by the equal-width test.
    pairs = []
    if len(panels) >= 4:
        pairs = [(0, 1), (2, 3)]
    elif len(panels) == 3:
        pairs = [(0, 1), (1, 2)]

    for r0, r1 in bands:
        for i, j in pairs:
            a0, a1 = panels[i]
            b0, b1 = panels[j]
