 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The grid has a regular separator lattice. Reflect each visible shape
    # from the left half of the cell array into its paired cell to the right.
    col_cuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    row_cuts = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]

    def spans(n, cuts):
        spans, start = [], 0
        for cut in cuts:
            spans.append((start, cut))
            start = cut + 1
        spans.append((start, n))
        return spans

    panels = spans(w, col_cuts)
    bands = spans(h, row_cuts)

    # For 4 panels, pair the outer cells with their inward neighbors. In the
    # 3-panel demo layout, the two left panels are a pair; the far-right narrow
    # margin is excluded by the equal-width test.
    pairs = []
    if len(panels) >= 4:
        pairs = [(0, 1), (2, 3)]
    elif len(panels) == 3:
        pairs = [(0, 1), (1, 2)]

    for r0, r1 in bands:
        for i, j in pairs:
            a0, a1 = panels[i]
            b0, b1 = panels[j]
            if a1 - a0 != b1 - b0:
                continue
            for r in range(r0, r1):
                for k in range(a1 - a0):
                    left = grid[r][a0 + k]
                    right = grid[r][b1 - 1 - k]
                    if left != 0:
                        out[r][b1 - 1 - k] = left
                    if right != 0:
                        out[r][a0 + k] = right
    return out

