 "content": "def transform(grid):
    """Apply the cellwise horizontal reflection rule demonstrated by examples."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Full colored rows/columns are dividers between panels.
    rowcuts = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    colcuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def intervals(n, cuts):
        ans, start = [], 0
        for c in cuts:
            ans.append((start, c))
            start = c + 1
        ans.append((start, n))
        return ans

    bands, panels = intervals(h, rowcuts), intervals(w, colcuts)
    for r0, r1 in bands:
        # Each pair of adjacent equal-sized panels is a two-sided reflection:
        # mirror every nonzero cell to its counterpart, retaining original cells.
        for i in range(len(panels) - 1):
            a0, a1 = panels[i]
            b0, b1 = panels[i + 1]
            if a1 - a0 != b1 - b0:
                continue
            width = a1 - a0
            for r in range(r0, r1):
                for k in range(width):
                    left, right = grid[r][a0 + k], grid[r][b1 - 1 - k]
                    if left:
                        out[r][b1 - 1 - k] = left
                    if right:
                        out[r][a0 + k] = right
    return out

