    col_cuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(size, cuts):
        result, start = [], 0
        for cut in cuts:
            result.append((start, cut))
            start = cut + 1
        result.append((start, size))
        return result

    bands, panels = spans(h, row_cuts), spans(w, col_cuts)
    n = len(panels)
    for r0, r1 in bands:
        occupied = [any(grid[r][c] != 0 for r in range(r0, r1) for c in range(a, b))
                    for a, b in panels]

        # Pairs already complete by reflection need no extra marks.
        paired = set()
        for i in range(n - 1):
            a0, a1 = panels[i]
            b0, b1 = panels[i + 1]
            if not (occupied[i] and occupied[i + 1]) or a1 - a0 != b1 - b0:
                continue
            if all(grid[r][a0 + k] == grid[r][b1 - 1 - k]
                   for r in range(r0, r1) for k in range(a1 - a0)):
                paired.update((i, i + 1))

        # A lone pattern is reflected toward the center of the panel array.
        # If two patterns would collide there, send the later one outward.
        for i in range(n):
            if not occupied[i] or i in paired:
                continue
            if i < (n - 1) / 2:
                choices = [i + 1, i - 1]
            else:
                choices = [i - 1, i + 1]
            s0, s1 = panels[i]
            chosen = None
            for j in choices:
                if j < 0 or j >= n:
                    continue
                d0, d1 = panels[j]
                if s1 - s0 != d1 - d0:
                    continue
                # Prefer a blank destination that will not conflict with an
                # already-completed reflection copied earlier in this band.
                conflict = False
                for r in range(r0, r1):
