    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Full nonzero rows/columns are the divider lattice.
    row_cuts = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    col_cuts = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(size, cuts):
        result, start = [], 0
        for cut in cuts:
            result.append((start, cut))
            start = cut + 1
        result.append((start, size))
        return result

    bands = spans(h, row_cuts)
    panels = spans(w, col_cuts)
    n = len(panels)

    for r0, r1 in bands:
        occupied = [any(grid[r][c] != 0 for r in range(r0, r1) for c in range(a, b))
                    for a, b in panels]
        paired = set()

        # Adjacent cells that already match under horizontal reflection are
        # complete pairs and should not produce extra copies.
        for i in range(n - 1):
            a0, a1 = panels[i]
            b0, b1 = panels[i + 1]
            if not (occupied[i] and occupied[i + 1]) or a1 - a0 != b1 - b0:
                continue
            if all(grid[r][a0 + k] == grid[r][b1 - 1 - k]
                   for r in range(r0, r1) for k in range(a1 - a0)):
                paired.update((i, i + 1))

        # Reflect each unpaired motif into an adjacent blank cell. Prefer the
        # cell on its right; if sizes do not match or it is occupied, try left.
        for i in range(n):
            if not occupied[i] or i in paired:
                continue
            s0, s1 = panels[i]
            for j in (i + 1, i - 1):
                if j < 0 or j >= n or occupied[j]:
                    continue
                d0, d1 = panels[j]
                if s1 - s0 != d1 - d0:
                    continue
                for r in range(r0, r1):
                    for k in range(s1 - s0):
                        color = grid[r][s0 + k]
                        if color:
                            out[r][d1 - 1 - k] = color
                break
    return out

