    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Full monochrome non-background lines partition the grid into cells.
    row_cuts = [r for r in range(h)
                if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    col_cuts = [c for c in range(w)
                if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(size, cuts):
        result, start = [], 0
        for cut in cuts:
            result.append((start, cut))
            start = cut + 1
        result.append((start, size))
        return result

    bands = spans(h, row_cuts)
    panels = spans(w, col_cuts)

    # Some bands show a color's complete mirrored pair; use that example to
    # identify which neighboring panels should be paired for this color.
    pair_for_color = {}
    for r0, r1 in bands:
        for i in range(len(panels) - 1):
            a0, a1 = panels[i]
            b0, b1 = panels[i + 1]
            if a1 - a0 != b1 - b0:
                continue
            colors = {grid[r][c] for r in range(r0, r1)
                      for c in range(a0, a1) if grid[r][c] != 0}
            colors |= {grid[r][c] for r in range(r0, r1)
                       for c in range(b0, b1) if grid[r][c] != 0}
            for color in colors:
                left = [[grid[r][a0 + k] == color for k in range(a1 - a0)]
                        for r in range(r0, r1)]
                right = [[grid[r][b1 - 1 - k] == color for k in range(b1 - b0)]
                         for r in range(r0, r1)]
                left_has = any(map(any, left))
                right_has = any(map(any, right))
                if left_has and right_has and left == right:
                    pair_for_color.setdefault(color, (i, i + 1))

    # In each band, copy a lone occurrence of a color into its learned paired
    # panel, reflecting across the separator. Existing complete pairs remain.
    for r0, r1 in bands:
        for color, (i, j) in pair_for_color.items():
            a0, a1 = panels[i]
            b0, b1 = panels[j]
            has_a = any(grid[r][c] == color for r in range(r0, r1) for c in range(a0, a1))
            has_b = any(grid[r][c] == color for r in range(r0, r1) for c in range(b0, b1))
            if has_a == has_b:
                continue
            if has_a:
                for r in range(r0, r1):
                    for k in range(a1 - a0):
                        if grid[r][a0 + k] == color:
                            out[r][b1 - 1 - k] = color
            else:
                for r in range(r0, r1):
                    for k in range(b1 - b0):
                        if grid[r][b0 + k] == color:
